-- Handbook remediation: catalog distractors now differ by use case and a concrete exclusion/selection constraint.
UPDATE products
SET title =
      CASE (CAST(substr(product_id, -3) AS INTEGER) % 15)
        WHEN 0 THEN 'background note' WHEN 1 THEN 'background note' WHEN 2 THEN 'background note' WHEN 3 THEN 'background note'
        WHEN 4 THEN 'background note' WHEN 5 THEN 'background note' WHEN 6 THEN 'background note' WHEN 7 THEN 'background note'
        WHEN 8 THEN 'background note' WHEN 9 THEN 'background note' WHEN 10 THEN 'background note' WHEN 11 THEN 'background note'
        WHEN 12 THEN 'background note' WHEN 13 THEN 'background note' ELSE 'Commutebackground note' END
      || '·' || brand,
    description =
      CASE (CAST(substr(product_id, -3) AS INTEGER) % 15)
        WHEN 0 THEN 'background note，background note。' WHEN 1 THEN 'background note，background notesleepbackground note。'
        WHEN 2 THEN 'background note，background noterecovery trainingbackground note。' WHEN 3 THEN 'background note，background noterecovery equipment。'
        WHEN 4 THEN 'background note，background notepurchaseconfirmation。' WHEN 5 THEN 'background note，background note。'
        WHEN 6 THEN 'background note，background note。' WHEN 7 THEN 'background note，background notetrainingbackground note。'
        WHEN 8 THEN 'background note，background note。' WHEN 9 THEN 'background note，background notehealthbackground note。'
        WHEN 10 THEN 'Storage only; verify earplug specifications separately.' WHEN 11 THEN 'background noterosterbackground note，background notecompanybackground note。'
        WHEN 12 THEN 'background note，background noteswellingrisk。' WHEN 13 THEN 'background note，background notetrainingbackground note。'
        ELSE 'background noteCommutebackground note，background note。' END
      || ' '
      || CASE CAST((CAST(substr(product_id, -3) AS INTEGER) - 1) / 15 AS INTEGER)
        WHEN 0 THEN 'Under 100 yuan, but still requires crew member confirmation.' WHEN 1 THEN 'background note，background note。'
        WHEN 2 THEN 'background note。' WHEN 3 THEN 'background noteMbackground notecompression socksbackground note。'
        WHEN 4 THEN 'background notestockbackground note，background notepurchasebackground note。' WHEN 5 THEN 'background notestockbackground note，background note。'
        WHEN 6 THEN 'Marketing uses exaggerated claims; exclude efficacy inference.' WHEN 7 THEN 'background note，background noteconfirmationbackground note。'
        WHEN 8 THEN 'background note。' WHEN 9 THEN 'background note。'
        WHEN 10 THEN 'Do not put sleep or cycle information in order notes.' WHEN 11 THEN 'Do not bundle with supplements or slimming capsules.'
        WHEN 12 THEN 'background note。' WHEN 13 THEN 'Arrival is after this cycle; do not rely on it for the plan.'
        ELSE 'Record as comparison only; exclude from pending purchase list.' END
      || ' background note=' || category || '；pricebackground note=' || base_price_minor || '；background note=' || return_policy || '。'
WHERE product_id LIKE 'product_recovery_noise_%';

